    'OverloadingChecker.scala': 'ProjectFortress/src/com/sun/fortress/scala_src/typechecker/OverloadingChecker.scala',
    'DesugarerVisitor.java': 'ProjectFortress/src/com/sun/fortress/interpreter/rewrite/DesugarerVisitor.java',
}


def hunks(path):
    out = subprocess.run(['git', '-C', WT, 'diff', '-U0', BASE, LAND, '--', path],
                         capture_output=True, text=True).stdout
    hs = []
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', out, re.M):
        a = int(m.group(1)); b = int(m.group(2) or 1)
        c = int(m.group(3)); d = int(m.group(4) or 1)
        if m.group(2) == '0': b = 0
        if m.group(4) == '0': d = 0
        hs.append((a, b, c, d))
    return hs


H = {k: hunks(v) for k, v in files.items()}


def mapl(k, n):
    """old line n -> new line, or None if the old line was changed."""
    off = 0
    for a, b, c, d in H[k]:
        if b > 0:
            if a <= n < a + b:
                return None
            if n >= a + b:
                off = (c + d) - (a + b)
        else:
            # pure insertion after old line a
            if n > a:
                off = (c + d) - (a + 1) + 1 if d else off
                off = d + (c - 1 - a) if False else (c + d - 1) - a
    return n + off


def old(k, n):
    return subprocess.run(['git', '-C', WT, 'show', '%s:%s' % (BASE, files[k])],
                          capture_output=True, text=True).stdout.splitlines()[n - 1]


def new(k, n):
    return subprocess.run(['git', '-C', WT, 'show', '%s:%s' % (LAND, files[k])],
                          capture_output=True, text=True).stdout.splitlines()[n - 1]


ledger = open(WT + '/explorations/fortress-gap-ledger.md').read().splitlines()
for r in [int(x) for x in sys.argv[1:]]:
    line = [l for l in ledger if l.startswith('| %d |' % r)][0]
    print('ROW', r, len(line))
    print(line)
    for m in re.finditer(r'(CodeGen\.java|Functionals\.scala|OverloadingChecker\.scala|DesugarerVisitor\.java)[^|]{0,160}', line):
        seg = m.group(0)
        k = m.group(1)
        nums = re.findall(r':(\d+)(?:-(\d+))?', seg.split(' at ')[0] if ' at ' in seg[:60] else seg[:80])
        print('  CITE', seg[:110])
        for s, e in nums:
            for n in [int(s)] + ([int(e)] if e else []):
                nn = mapl(k, n)
                print('    %s:%d -> %s | old: %s' % (k, n, nn, old(k, n).strip()[:70]))
                if nn:
                    print('        new: %s' % new(k, nn).strip()[:70])
    print()

